import{_ as t,o as e,c as a,a2 as i}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"重放迁移合同基准","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/testing/contracts","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"testing/contracts.md","filePath":"testing/contracts.md"}'),n={name:"testing/contracts.md"};function o(p,s,d,l,r,c){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="重放迁移合同基准" tabindex="-1">重放迁移合同基准 <a class="header-anchor" href="#重放迁移合同基准" aria-label="Permalink to &quot;重放迁移合同基准&quot;">​</a></h1><p>本指南面向迁移 Lab Word 服务的开发者。M0 使用真实 Rust HTTP/SSE 服务，重放已交付的 Core、Foundation #2–#11 和 #26–#28。新 TypeScript 服务尚未实现。#29–#40 的产品行为不属于此基准。</p><h2 id="得到第一个结果" tabindex="-1">得到第一个结果 <a class="header-anchor" href="#得到第一个结果" aria-label="Permalink to &quot;得到第一个结果&quot;">​</a></h2><p>在仓库根目录执行。需要仓库指定的 Node、pnpm、Rust、Docker。Docker daemon 必须可用。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.test.ts</span></span></code></pre></div><p>runner 编译独立 Rust target，创建隔离 PostgreSQL、Redis、RustFS 和 Mailpit，执行迁移，再启动 API 和文件清理 Worker。它通过 HTTP 创建首个 Owner。用例中的其他注册用户是 Member。</p><p>终端显示实际收集和执行的测试数量。<code>CORE-02</code> 验证缺少 CSRF 的写入被拒绝，Lab 列表保持不变，正确写入随后成功。<code>CORE-03</code> 验证有效 Agent、无效 Bearer 不回退 Cookie，以及撤销后的拒绝。</p><p>未选择文件时，<code>test:contract</code> 运行 Core/API 小片段。完整合同使用下节的 <code>test:contract:all</code>。</p><p>测试只通过 HTTP 准备业务，通过 HTTP/SSE 观察结果。ID 和游标原样传回服务。进程控制用于真实启动、停止和重启。</p><h2 id="运行全部必需合同" tabindex="-1">运行全部必需合同 <a class="header-anchor" href="#运行全部必需合同" aria-label="Permalink to &quot;运行全部必需合同&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract:all</span></span></code></pre></div><p>六个 profile 各有独立数据和 owned ledger。任何 profile 失败都会使命令失败。</p><table tabindex="0"><thead><tr><th>Profile</th><th>验证</th><th>显式测试配置</th></tr></thead><tbody><tr><td><code>baseline</code></td><td>身份、权限、资产、世界、设备、SSE、历史、记录、趋势和 API 合同</td><td>生产默认额度与保留期</td></tr><tr><td><code>file-ttl</code></td><td>签名上传/下载过期及重新授权恢复</td><td>下载 2 秒、上传会话 5 秒</td></tr><tr><td><code>session-ttl</code></td><td>会话 idle/absolute 过期、SSE 结束与新登录恢复</td><td>idle 60 秒、absolute 65 秒</td></tr><tr><td><code>retention</code></td><td>公开清理、真实缺口、在途任务、最后值及过期命令 receipt</td><td>观测 2 秒、结束记录 3 秒</td></tr><tr><td><code>rate</code></td><td>主额度 20/60/600、429、<code>Retry-After</code> 与窗口恢复</td><td>窗口 5 秒；主额度保持默认</td></tr><tr><td><code>capacity</code></td><td>1000 Entity/1000 Scene Node 和超限拒绝</td><td>关闭限流，独立验证容量</td></tr></tbody></table><p>baseline 按 Core/API、资产世界、设备、历史和 SSE 分五批，各批使用新进程和独立数据。这样不会让多个测试文件的轮询耗尽同一 TCP 客户端的正常额度。总共六种 profile、十批真实运行。</p><p>正常限流仍是注册 20、认证 60、资源 600，每 60 秒。<code>fallback_limit</code> 的 5/20/120 和 4096 桶容量是兼容配置。它们不能代替正常额度。旧 Redis 故障模式不进入新服务的共同 oracle。</p><p>开发中可定向运行已编译目标：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sse.test.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retention</span></span></code></pre></div><p><code>--no-build</code> 只适用于已编译当前 Rust 源码的 target。它不证明旧二进制与当前候选一致。</p><h2 id="阅读覆盖和失败" tabindex="-1">阅读覆盖和失败 <a class="header-anchor" href="#阅读覆盖和失败" aria-label="Permalink to &quot;阅读覆盖和失败&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/tests/contract/behavior-matrix.json" target="_blank" rel="noreferrer">行为矩阵</a> 为每条行为登记来源、正常结果、拒绝后状态、恢复、用例和预算。<code>public</code> 是公开 HTTP/SSE；<code>configuration</code> 使用现有配置。<code>internal-supplement</code> 明确由后续票承担内部规则或用例验证。<code>gap</code> 表示必需覆盖仍缺失，不能宣告 M0 完成。</p><p>24 小时尖峰造样、坏质量、旧来源、重复 sequence、精确 SQL 计量及 SSE 恰好 8 条待发不能由当前公开入口可靠诱发。矩阵将它们映射到 #48/#50。现有 SQL/Runtime 先例不是纯 HTTP 证据。真实事件大小、断线和凭据撤销仍由共同合同验证。</p><p>运行证据在 <code>.scratch/vnext-m0/runs/&lt;run-id&gt;/</code>。<code>results.json</code> 保存实际发现、通过与失败数量；<code>owned-resources.json</code> 保存资源意图、身份、消费者和前后盘点。<code>.scratch/vnext-m0/current.json</code> 指向最近一次 run。完整命令还写入 suite manifest。</p><p>先辨别失败类型：编译、零收集和夹具错误不算业务 red。业务失败需保留原断言和预算。修复夹具不能改变生产默认值。Rust 的 24h 容量用例只在本用例采用 172800 秒观测保留。独立的默认 86400 秒 HTTP 用例验证真实裁剪和保留缺口。生产默认值不变。</p><h2 id="比较保留-api" tabindex="-1">比较保留 API <a class="header-anchor" href="#比较保留-api" aria-label="Permalink to &quot;比较保留 API&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts:baseline:check</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/scripts/lib/contract-openapi.ts" target="_blank" rel="noreferrer">比较工具</a> 只过滤明确移除的知识库、通知、邮件密码重置、通用 jobs 和 system cache 路由。它按引用保留 DTO 和安全声明。对象声明顺序不影响结果；DTO、operationId、响应状态、错误和安全变化会报告 JSON 路径。</p><p>使用 <code>node scripts/contract-api-baseline.mjs --input &lt;候选-openapi.json&gt;</code> 比较另一份 OpenAPI。<code>--write</code> 会重写基准，只在已批准合同变更时使用。M0 不固定 schema 版本 28。Rust 版本期望从当前构建和迁移源导出；其他目标报告自己的实际版本。</p><h2 id="切换目标与恢复资源" tabindex="-1">切换目标与恢复资源 <a class="header-anchor" href="#切换目标与恢复资源" aria-label="Permalink to &quot;切换目标与恢复资源&quot;">​</a></h2><p>Rust 是当前唯一内置 adapter。其他可执行目标可通过 descriptor 接入；这不表示新服务已经存在：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/absolute/path/to/server&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [] }</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candidate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --descriptor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/to/target.json</span></span></code></pre></div><p>目标获得 <code>APP_BIND</code>、<code>APP_ORIGIN</code> 和独立 <code>CONTRACT_DATA_DIRECTORY</code>。它需自行初始化该目录，并提供相同 HTTP 合同。非 Rust 目标不会创建 Docker 服务。可选 <code>version</code>、<code>schemaVersion</code> 用于核对实际目标 metadata。</p><p>正常结束、失败、超时和 SIGINT/SIGTERM 都会停止本次消费者并清理资源。异常终止后，在原 supervisor 已停止时执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recover</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/vnext-m0/runs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/owned-resources.json</span></span></code></pre></div><p>恢复先核对进程组的 PID、启动 token、PGID/session 及子进程 proof，再核对容器 labels 和不可变 ID。身份不明或被替换的资源会保留。工具只删除 owned ledger 内已证明归属的资源，使用 <code>docker rm -f -v</code> 回收匿名卷。它不会执行全局 prune，也不会删除既有根服务或持久卷。</p><p>M0 Rust/Docker 与进程组恢复验证范围是 Linux。Windows 的新目标 adapter 和子进程验证由后续基础票完成，当前不宣称 Windows 通过。</p><p>用 <code>pnpm test:contract:lifecycle</code> 检查真实中断和 wrapper 子进程恢复。该命令创建自己的隔离旧栈。CI 在最终候选运行完整合同；本地绿色和 Draft PR 不能代替最终 CI。</p><hr><p>源码版本：<code>d3878fce3770</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/docs/testing/contracts.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,39)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
